<x-app-layout>
<div class="p-6 max-w-6xl mx-auto w-full"><div class="mb-7"><p class="text-sm font-semibold text-primary mb-2">Storefront settings</p><h1 class="text-3xl font-bold text-gray-900">Connect your custom domain</h1><p class="mt-2 text-sm text-gray-500">Use your own domain for a memorable storefront address.</p></div><div id="msg" class="hidden mb-5 rounded-xl px-4 py-3 text-sm"></div>
<div class="grid gap-6 lg:grid-cols-2"><section class="bg-white rounded-2xl border p-8 shadow-sm"><h2 class="font-bold text-gray-900">Add a domain</h2><p class="text-sm text-gray-500 mt-1 mb-6">Enter the domain you already own.</p><form id="form" novalidate><label class="block text-sm font-semibold text-gray-700 mb-2">Domain name</label><div class="flex"><span class="px-3 py-3 rounded-l-xl border border-r-0 bg-gray-50 text-gray-400 text-sm">https://</span><input id="domain" required autocomplete="url" spellcheck="false" placeholder="www.yourstore.com" class="w-full rounded-r-xl border-gray-200 focus:border-primary focus:ring-primary text-sm"></div><button id="submit" class="mt-5 rounded-xl bg-primary px-5 py-3 text-sm font-semibold text-white">Connect domain</button></form><div class="mt-7 rounded-xl bg-blue-50 p-4 text-sm text-blue-800">After adding it, update the DNS record at your domain provider. DNS changes can take a few minutes.</div></section><section class="bg-gray-900 rounded-2xl p-8 text-white"><h2 class="font-bold mb-3">Quick DNS setup</h2><p class="text-sm text-gray-300 mb-5">Add this record at your domain provider.</p><div id="dns" class="text-sm text-gray-300">Loading DNS instructions...</div><p class="mt-6 text-xs text-gray-400">After DNS is ready, click Verify below.</p></section></div>
<section class="mt-6 bg-white rounded-2xl border p-8 shadow-sm"><h2 class="font-bold text-gray-900">Connected domains</h2><p class="text-sm text-gray-500 mt-1 mb-5">Your free storefront and custom domains.</p><div id="list" class="space-y-3">Loading domains...</div></section></div>
@push('scripts')<script>(()=>{const api='/api/v1/store/domains',token=document.querySelector('meta[name="csrf-token"]').content,msg=document.getElementById('msg'),list=document.getElementById('list'),dns=document.getElementById('dns');const req=async(u,o={})=>{let r=await fetch(u,{credentials:'same-origin',...o,headers:{'X-Requested-With':'XMLHttpRequest',Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':token}}),d=await r.json();if(!r.ok)throw d;return d};const notice=(t,e=false)=>{msg.textContent=t;msg.className='mb-5 rounded-xl px-4 py-3 text-sm '+(e?'bg-red-50 text-red-700':'bg-green-50 text-green-700')};const errorText=e=>e?.errors?.domain?.[0]||e?.message||e?.error||'Something went wrong. Please try again.';const load=async()=>{try{let r=await req(api),i=r.data.dns_instructions;dns.innerHTML='<div class="rounded-xl bg-white/10 p-4 leading-7"><b>Type:</b> '+i.record+'<br><b>Name:</b> '+i.name+'<br><b>Value:</b> <span class="text-blue-200">'+i.value+'</span></div>';list.innerHTML=r.data.items.map(d=>'<div class="flex justify-between items-center gap-3 rounded-xl border p-4"><div><b>'+d.domain+'</b><p class="text-xs text-gray-400">'+(d.is_primary?'Primary · ':'')+(d.type==='custom'?d.ssl_status:'Free storefront domain')+'</p></div>'+(d.type==='custom'?'<button data-id="'+d.id+'" class="verify rounded-lg border border-primary px-3 py-2 text-xs text-primary">'+(d.verified_at?'Verified':'Verify DNS')+'</button>':'<span class="text-xs text-green-700">Active</span>')+'</div>').join('');document.querySelectorAll('.verify').forEach(b=>b.onclick=async()=>{try{await req(api+'/'+b.dataset.id+'/verify',{method:'POST'});notice('DNS verified. SSL is being provisioned.');load()}catch(e){notice(errorText(e),true)}})}catch(e){notice(errorText(e),true)}};document.getElementById('form').onsubmit=async e=>{e.preventDefault();try{await req(api,{method:'POST',body:JSON.stringify({domain:document.getElementById('domain').value})});document.getElementById('domain').value='';notice('Domain added. Update DNS, then verify it.');load()}catch(e){notice(errorText(e),true)}};load()})();</script>@endpush
</x-app-layout>